/** Reviewed product facts only. Never populate this catalog from settings, logs or business data. */
export type FeaturePermission = 'read'|'write'|'admin'|'linked'|'tool';
export type Feature = {topicId:string;title:string;text:string;route:string;permission:FeaturePermission;keywords:string[];steps:string[];limitations:string[];sourceFiles:string[]};
function feature(topicId:string,title:string,route:string,permission:FeaturePermission,keywords:string,steps:string[],limitations:string[],sourceFiles:string[]):Feature{return {topicId,title,text:'',route,permission,keywords:keywords.split(' '),steps,limitations,sourceFiles};}
export const featureCatalog:Feature[]=[
 feature('konto','Persönliche Notizen in der Menüleiste','/benutzerkonto?bereich=tools','tool','notizen notiz notizblock merkzettel menüleiste werkzeug automatisch speichern',[ 'Das Notizen-Symbol links neben dem Benutzermenü öffnet deinen persönlichen Notizblock.','Text eingeben; die Notiz wird automatisch gespeichert. Zuklappen mit X oder Escape, später wieder öffnen.','Unter Benutzerkonto → Werkzeuge lässt sich Notizen persönlich ein- oder ausblenden.'],['Die Rolle muss das Notizen-Werkzeug freigeben. Administratoren erhalten alle Werkzeuge. Notizen benötigen keine Fach-App-Schreibrechte und betreffen ausschließlich dein eigenes Konto.','Noch nicht bestätigte Änderungen werden verschlüsselt auf dem Browsergerät gesichert. Nach erneutem Öffnen wird die offene Fassung weitergespeichert; bei Verbindungsfehlern bleibt sie erhalten.','Unabhängige Textänderungen werden zusammengeführt. Bei überschneidenden Änderungen zeigt HeyElli beide Fassungen, statt eine still zu überschreiben.','Auf Smartphone-Breite sind Menüleisten-Werkzeuge ausgeblendet. Elli liest keine persönlichen Notizinhalte.'],['src/apps/notizen/notes-tool.tsx','src/apps/notizen/local.ts','src/apps/notizen/repository.ts','src/app/api/benutzerkonto/notizen/route.ts','src/platform/app-access/tools.ts']),
 feature('service','Auftragsaktionen und Status wechseln','/servicehub?ansicht=orders','write','auftragsstatus status ändern mobil ausgeben stornieren manuell storniert symbole tooltip',[ 'Service → Aufträge öffnen und einen Auftrag auswählen. Die Aktionen stehen oben links neben dem Status als Symbole mit Tooltips.','Das Kalendersymbol öffnet den Einsatz im PlanBoard. Bei unvollständiger Planung öffnet Termin vergeben die vorhandene Terminvergabe. Das Briefsymbol bereitet eine Terminbestätigung vor.','Auf den aktuellen Auftragsstatus klicken und eine verfügbare Aktion wählen. Mobil ausgeben zeigt vorher die Haupttechniker. Statuswechsel und Ausgabe ausdrücklich bestätigen.'],['Auftragsänderungen benötigen Service-Schreibrecht. Kalenderverweise benötigen zusätzlich PlanBoard-Leserecht.','Mobile Ausgabe benötigt Haupttechniker für alle Einsätze. Für Mobil abgeholt wird Manuell stornieren angeboten, für andere nicht stornierte Aufträge Stornieren. Mobile Systemstatus werden nicht als freie Statuswechsel angeboten.','Zwischenzeitlich geänderte Aufträge werden nicht überschrieben. Nach einer verlorenen Antwort verwendet erneutes Bestätigen dieselbe Vorgangskennung. Status und Ausgabe werden mit Benutzer und Zeitpunkt protokolliert.','Welche Aktionen verfügbar sind, wird beim Öffnen geprüft. Nicht freigegebene Schreibwege bleiben deaktiviert.'],['src/apps/servicehub/akten/file-toolbar.tsx','src/apps/servicehub/akten/order-status.tsx','src/apps/servicehub/akten/order-actions-server.ts','src/platform/pds/simulator/service-actions.ts']),
 feature('service','Vom Serviceauftrag zum Kalendertermin','/servicehub?ansicht=orders','read','ressourcenkalender kalendertermin springen anzeigen einsatz ressourcenmeister',[ 'Service → Aufträge öffnen und den Auftrag auswählen.','Oben in der Auftragsakte das Kalendersymbol mit dem Tooltip Im PlanBoard anzeigen wählen. Der Kalender zeigt den zugehörigen Tag und Techniker und hebt den Termin hervor.'],['Zusätzlich ist Leserecht für den PlanBoard erforderlich. Der Link verändert den Termin nicht. Ohne geplanten Beginn wird kein Kalenderverweis angezeigt. Die separate Terminvergabe mit ihren bisherigen Berechtigungen bleibt unverändert.','Bei mehreren Einsätzen besitzt jeder geplante Einsatz seinen eigenen Verweis. Die Ressourcenauswahl wird für diesen Aufruf vorübergehend übergangen, ohne persönliche Einstellungen zu speichern. Der über den Link gesetzte Mitarbeiter steht im Suchfeld Ressourcen. Mit dem X oder durch Bearbeiten des Felds wird der Linkfilter entfernt; anschließend gilt wieder die persönliche Ressourcenauswahl.'],['src/apps/servicehub/akten/order-incident.tsx','src/apps/servicehub/akten/model.ts','src/apps/servicehub/akten/server.ts','src/apps/planboard/kalender/calendar.tsx']),
 feature('service','Rücklauf- und Abschlusskontrolle','/servicehub?ansicht=orders','read','rücklauf rückläufe abschlusskontrolle ausgeführt ausführung arbeitsnachweis rücklaufpositionen rücklaufdokumente',[ 'Service → Aufträge → Auftragsakte → Einsatzmappe → Rücklauf & Abschlusskontrolle öffnen. Zugeordnete Rückläufe erscheinen automatisch. Einen Rücklauf auswählen, um seinen Nachweis zu öffnen.','HeyElli prüft die Zuordnung über serviceauftragebeneUUID. Die Ansicht zeigt ausgeführte Arbeiten, Ausführungsdatum und Rücklaufstatus je zugehörigem Einsatz.','Rücklaufpositionen zeigt Artikel, Mengen und Beschreibungen getrennt von den ursprünglichen Auftragspositionen. Rücklaufdokumente öffnet die PDS-Originale.'],['Service-Leserecht genügt; keine Abschlussbuchung oder Schreibfreigabe erforderlich.','Die automatische Suche nutzt eine ausdrücklich konfigurierte, lesende PDS-Datenansicht mit ruecklaufUUID und serviceauftragebeneUUID. Die normalen Rücklaufdetails bestätigen jede Zuordnung. Ohne freigegebene Ansicht ist die automatische Suche nicht eingerichtet; die Anzeige ist kein vollständiger Abschlussnachweis. Ein geplanter Termin ersetzt kein Ausführungsdatum.','Bei Rückläufen für mehrere Aufträge werden nur zugeordnete Einsätze angezeigt. Gemeinsame Grunddatendokumente bleiben gesperrt; eindeutig zugeordnete Einsatzdokumente sind verfügbar.','Aktualisierung im Hintergrund. Bei Verbindungsfehlern bleibt der letzte Stand ausdrücklich unbestätigt sichtbar. Fehlende Ansichten, veraltete Bezüge und Lesebudgets werden gemeldet; keine Zuordnung anhand ähnlicher Namen oder Kundennummern. Keine Dateikopien, Preise oder interne Kalkulation.'],['src/apps/servicehub/akten/return-control.tsx','src/apps/servicehub/akten/return-reader.ts','src/platform/pds/api/return-links.ts','src/apps/servicehub/akten/dispatch-server.ts']),

 feature('service','Material- und Leistungsliste','/servicehub?ansicht=orders','read','material materialliste leistungen leistungsliste artikel mengen einheiten positionen unterpositionen beschreibungen',[ 'Service → Aufträge öffnen und einen Auftrag auswählen. In der Einsatzmappe Material & Leistungen öffnen.','Die Positionen stehen je Einsatz mit Positionsnummer, Artikel- oder Leistungsbezeichnung, Positionstyp, Menge und gelieferter Einheit. Unterpositionen und Alternativ-/Bedarfspositionen sind gekennzeichnet.','Beschreibung & Details öffnet lange Leistungsbeschreibungen, Zusatztexte sowie vorhandene Bestell-, Hersteller- und EAN-Nummern. Weitere Positionen anzeigen erweitert die Liste.'],['Service-Leserecht genügt. Die Liste verändert keine PDS-Daten und benötigt keine Schreibfreigabe.','Menge und gegebenenfalls abweichende Gesamtmenge werden direkt aus PDS übernommen. Keine Summierung unterschiedlicher Einheiten und keine eigene Multiplikation von Unterpositionen. Fehlende oder ungültige Mengen werden ausdrücklich nicht als null Stück ausgegeben.','Fehlende Positionsliste und tatsächlich leere Positionsliste sind getrennt gekennzeichnet. Quellenausfälle erhalten den letzten geladenen Stand mit einem Fehlerhinweis.','Die Liste ist eine Einsatzunterlage, kein Nachweis verbrauchter oder verfügbarer Lagerbestände. Preise und interne Kalkulationsfelder werden nicht angezeigt. Aktuelle Katalogdaten ersetzen keine Auftragspositionen.','Aktualisierung im Hintergrund; Texte werden sicher als Klartext dargestellt. Keine zusätzliche Dateikopie oder automatische Dokumentablage.'],['src/apps/servicehub/akten/material-list.tsx','src/apps/servicehub/akten/material-reader.ts','src/apps/servicehub/akten/material-model.ts','src/apps/servicehub/akten/dispatch-server.ts']),

 feature('service','Anlagenchronik der technischen Einheit','/servicehub?ansicht=files','read','anlagenchronik anlagenverlauf anlagengeschichte chronik technische einheit wartungsintervalle berichte unterlagen',[ 'Service → Kunden & Objekte öffnen und eine technische Einheitenakte auswählen. Die Anlagenchronik steht direkt in der Akte.','Alle, Einsätze, Wartungen oder Berichte & Unterlagen wählen. Die Chronik zeigt neueste Daten zuerst, gruppiert nach Monaten; Einträge ohne verlässliches Datum stehen am Ende.','Auftragsakte öffnen führt zum zugehörigen Auftrag. Unterlage öffnen lädt ein PDS-Original oder öffnet eine Datei aus dem SharePoint-Ordner dieser Einheit. Weitere Einträge anzeigen erweitert die Liste.'],['Service-Leserecht genügt; die Chronik verändert keine Fach- oder Dokumentdaten. Nur Einsätze mit genau dieser technischen Einheitenzuordnung werden übernommen.','Ein Servicetermin ist kein Ausführungsnachweis. Bei Wartungen wird die aktuell gelieferte nächste Fälligkeit gezeigt, keine erfundene Historie vergangener Durchführungen.','Dokumente zeigen ihr hinterlegtes Datum, SharePoint-Dateien den Änderungszeitpunkt. Auftragsunterlagen können mehrere Einheiten betreffen und werden entsprechend gekennzeichnet. Eine unbekannte Unterlage wird nicht automatisch als Wartungsbericht bezeichnet.','Bei Quellenausfällen ist die Chronik ausdrücklich unvollständig; andere Bereiche bleiben bedienbar. Die Aktualisierung erfolgt im Hintergrund. SharePoint benötigt die bestehende Freigabe.','Die Ansicht umfasst vorhandene API-Daten, kein Archiv gelöschter Einsätze. Rückläufe ohne dokumentierten Listenweg beziehungsweise bekannte Kennungen werden nicht erfunden.'],['src/apps/servicehub/akten/chronicle.tsx','src/apps/servicehub/akten/chronicle-reader.ts','src/apps/servicehub/akten/chronicle-server.ts','src/apps/servicehub/akten/chronicle-model.ts']),

 feature('service','Terminbestätigung an Kunden','/servicehub?ansicht=orders','write','terminbestätigung kunde mail email outlook graph bestätigen nachricht',[ 'Service → Aufträge öffnen und einen Auftrag auswählen. In der Einsatzmappe beim geplanten Einsatz Terminbestätigung öffnen.','Empfänger prüfen: Geschäftliche Kundenkontakte aus PDS stehen zur Auswahl; ohne passende Adresse die E-Mail-Adresse selbst eintragen. Die Vorschau zeigt Auftrag, Objektadresse, Beginn, Ende und Haupttechniker.','In Outlook öffnen übergibt nach Bestätigung an das eingerichtete E-Mail-Programm; dort selbst senden. Graph-Optionen erscheinen nur bei aktivem Modul. Der konkrete Versandmodus steht vor der Bestätigung im Dialog. Erst die separate Bestätigung reiht die Nachricht in die bestehende Versandwarteschlange ein.'],['Service-Schreibrecht oder Administrator erforderlich. Termin, Ende, aufgelöster Haupttechniker und Objektadresse müssen vorhanden sein.','Termin, Adresse, Haupttechniker, Kontakte und Versandmodus werden vor jeder neuen Übergabe erneut geprüft. Bei Änderungen die Vorschau neu laden.','Identische Graph-Bestätigungen desselben Einsatzes an denselben Empfänger werden im gleichen Versandmodus und mit gleichem Absender nur einmal eingereiht; Antwortverluste lassen sich mit derselben Anfrage wiederholen. Ein Wechsel der Betriebsart versendet bereits erfasste Nachrichten nicht erneut.','Outlook-Vorbereitung ist kein Versandnachweis; Graph-Warteschlange ist kein Zustellnachweis. Nachträgliche Terminänderungen erzeugen keine automatische Kundenmail und ändern bereits eingereihte Nachrichten nicht.','Der Text wird aus Einsatzdaten erzeugt und ist in HeyElli schreibgeschützt. Im E-Mail-Programm kann er bearbeitet werden. Elli versendet diese Nachrichten nicht selbst.'],['src/apps/servicehub/akten/confirmation-dialog.tsx','src/apps/servicehub/akten/confirmation-reader.ts','src/apps/servicehub/akten/confirmation-server.ts','src/apps/servicehub/akten/confirmation-repository.ts']),

 feature('service','Dynamische Einsatzmappe','/servicehub?ansicht=orders','read','einsatzmappe dokumentauswahl dokumente einsatz vorbereiten pds sharepoint bmacloud',[ 'Service → Aufträge öffnen und einen Auftrag auswählen. Die Einsatzmappe stellt Kunde, Objektadresse, Termin und Haupttechniker als Fokusfelder dar. Begleiter und Ansprechpartner stehen ergänzend dabei. Lange Auftragsbeschreibungen lassen sich vollständig aufklappen; der gespeicherte Meldetext bleibt erhalten.','Dokumente auswählen öffnen und gewünschte PDS-Dokumente sowie Dateien aus den zugeordneten SharePoint-Aktenordnern einschalten. Die Auswahl speichert automatisch gemeinsam am Auftrag.','Auswahl anzeigen zeigt die gewählten Dokumentverweise. Links öffnen die Originalquelle; PDS-Dateien werden bei Bedarf heruntergeladen. BMACloud-Verknüpfungen stehen darunter.'],['Service-Leserecht erlaubt das Ansehen. Änderungen der gemeinsamen Dokumentauswahl benötigen Service-Schreibrecht oder Administrator.','Dokumente werden nicht kopiert. Die Auswahl enthält ausschließlich Verweise, keine Offline-Dateien oder eingefrorenen Datenstände.','SharePoint und BMACloud benötigen ihre jeweilige Freigabe und beim Öffnen eigene Zugriffsrechte. Nicht erreichbare Quellen behalten die Auswahl; nicht bestätigte Dokumente zeigen keinen aktuellen Link.','Die ersten 100 SharePoint-Dateien je Aktenordner sind auswählbar; die Mappe verwaltet höchstens 100 ausgewählte Verweise. Unabhängige Auswahlen bleiben bei parallelen Änderungen erhalten; widersprüchliche Auswahlstände werden neu geladen.','Elli erklärt die Mappe, liest aber keine Dokumentinhalte.'],['src/apps/servicehub/akten/dispatch-pack.tsx','src/apps/servicehub/akten/order-incident.tsx','src/apps/servicehub/akten/dispatch-server.ts','src/apps/servicehub/akten/dispatch-repository.ts']),

 feature('service','Kunden anheften und Arbeitslisten','/servicehub?ansicht=orders','read','anheften angeheftet pin kunde kunden seitenleiste arbeitslisten offene aufträge alle kunden einklappen',[ 'Die Seitenleiste in Service zeigt Arbeitslisten mit Zählern: Cockpit, Alle Aufträge, Ohne Termin, Ohne Haupttechniker, Heute geplant und Fällige Wartungen.','Unter Offene Aufträge stehen die Kunden mit offenen Aufträgen; ein Klick zeigt nur deren Aufträge. Alle Kunden … öffnet die Kundenliste von A bis Z mit Suche und den Filtern Alle, Angeheftet und Mit offenen Aufträgen.','Kundenakte öffnen und mit der Stecknadel in der Werkzeugleiste den Kunden anheften oder lösen. Angeheftete Kunden stehen persönlich unter Angeheftet.'],['Angeheftete Kunden gelten nur für das eigene Konto und die aktive Datenquelle.','Die Seitenleiste lässt sich über das Symbol oben links einklappen.'],['src/apps/servicehub/akten/workspace.tsx','src/apps/servicehub/akten/customer-files.tsx','src/apps/servicehub/akten/pin-store.ts']),
 feature('service','Fällige Wartungen und Auftragsvorschau','/servicehub?ansicht=maintenance','read','wartung wartungen fälligkeit fällig intervall wartungsvertrag',[ 'ServiceHub → Fällige Wartungen öffnen und eine Zeile auswählen. Rechts erscheinen Fälligkeit, Vertragsdaten, Leistungsumfang und Angaben zur technischen Einheit. Mit Pfeil hoch und runter die Zeile wechseln, mit Enter die Details öffnen, mit Escape zur Liste zurückkehren.','Kategorien und Filteroptionen grenzen die Fälligkeit ein. Das Filtersymbol pausiert den Filter. Die Lupe oben rechts sucht nach Kunde, Objekt, Einheit, Vertrag und Wartung.','Mit Service-Schreibrecht öffnet Auftrag erzeugen in der Aktenwerkzeugleiste eine Vorschau. Vorgesehener Folgeablauf für Wartungen: bestätigte Erzeugung → Techniker und Termin zuordnen, mit denselben Planungsfeldern wie im CaseDesk. Dieser Übergang bleibt bis zur Freigabe der Wartungserzeugung inaktiv.'],['Die tatsächliche Auftragserzeugung ist fest gesperrt, auch für Administratoren. Deshalb wird die nachgelagerte Terminvergabe in der aktuellen Oberfläche noch nicht durch eine Anlage ausgelöst. Es wird weder ein Serviceauftrag angelegt noch die Fälligkeit fortgeschrieben.','Vor Implementierung/Freigabe müssen Intervallbezug, Positionen, Pflichtfelder, Fortschreibung und Wiederholungsschutz mit PDS geklärt werden. Die bestehende PDS-Freigabe aktiviert diesen Ablauf nicht.','Nur das gelieferte nächste Datum wird gelesen; keine eigene Wiederholungsberechnung. Fehlende Daten und unvollständiges Laden werden ausdrücklich angezeigt.'],['src/apps/servicehub/akten/maintenance-workspace.tsx','src/apps/servicehub/akten/maintenance-reader.ts','src/apps/servicehub/akten/maintenance-preview.tsx']),
 feature('service','Kunden, Objekte und technische Einheiten ausblenden','/servicehub?ansicht=files','read','ausblenden einblenden blende einzelne ausgeblendet kunde objekt technische einheit persönlich',[ 'Service → Kunden & Objekte öffnen und eine Kunden-, Objekt- oder technische Einheitenakte auswählen.','Ausblenden wählen. Die persönliche Übersicht verbirgt auch untergeordnete Einträge.','Unter Kunden & Objekte → Ausgeblendete Einträge den gewünschten Eintrag mit Einblenden wiederherstellen.'],['Es werden keine Fachdaten gelöscht oder in PDS geändert. Aufträge bleiben sichtbar. Die Auswahl im CaseDesk berücksichtigt dieselben persönlichen Ausblendungen einschließlich untergeordneter Objekte und technischer Einheiten.','Die Auswahl gilt pro Benutzer und Datenquelle, wird dauerhaft gespeichert und benötigt nur Service-Leserecht.','Ein separat ausgeblendetes Kind bleibt nach dem Einblenden seines Elternteils verborgen, bis es ebenfalls eingeblendet wird.'],['src/apps/servicehub/akten/workspace.tsx','src/apps/servicehub/akten/visibility-model.ts','src/apps/servicehub/akten/visibility-server.ts']),
 feature('einstellungen','SharePoint-Ablagestruktur pflegen','/einstellungen?bereich=sharepoint&seite=sharepoint:storage','admin','sharepoint ablagestruktur ordnerstruktur ablagetypen unterordner umbenennen übernahme hash ordner',[ 'Einstellungen → SharePoint → Ablagestruktur öffnen.','Ablagetypen umbenennen, ergänzen, ausblenden oder sortieren und speichern.','Unter Bisherige Ablage übernehmen eine Vorschau erstellen, prüfen und Übernahme starten.'],['Ablagetypen werden nie gelöscht, nur ausgeblendet; vorhandene Ordner behalten ihren Namen.','Die Übernahme verschiebt Dateien nach Sonstiges in die neue Struktur und löscht nichts; nicht zuordenbare Ordner bleiben unverändert.'],['src/platform/sharepoint/storage-panel.tsx','src/platform/sharepoint/layout.ts']),
 feature('einstellungen','SharePoint einrichten und freigeben','/einstellungen?bereich=sharepoint','admin','sharepoint microsoft dokumente bibliothek site website dateien integration secret freigabe',[ 'Einstellungen → Integrationen → SharePoint öffnen.','Unter Verbindung die Microsoft-App, Site-ID, Bibliothek und Stammordner geschützt einrichten. Ein leeres Secret-Feld verwendet das gespeicherte Secret.','Unter Prüfung & Freigabe die Verbindung testen und erst danach SharePoint ausdrücklich freigeben.','Die Anleitung ist auch als Markdown herunterladbar.'],['Sites.Selected und eine gesonderte Websitefreigabe mit Schreibrecht durch die Microsoft-Administration sind erforderlich.','Einrichtung, Test und Wiederherstellung aktivieren die Integration nicht automatisch. Jede Konfigurationsänderung deaktiviert sie.','Secret und Tokens ausschließlich im geschützten Formular eingeben, nicht in Elli. Elli kann den aktuellen Freigabestatus nicht auslesen.'],['src/platform/sharepoint/panel.tsx','src/platform/sharepoint/repository.ts','src/platform/sharepoint/guide.ts']),
 feature('service','SharePoint-Dokumente ansehen','/servicehub','read','dateien dokumente sharepoint akte kunde objekt technische einheit vertrag auftrag öffnen',[ 'Eine Kunden-, Objekt-, technische Einheiten- oder Auftragsakte öffnen.','Unter Dokumente · SharePoint die Dateien nach Ablagetyp (z. B. Mails, Berichte, Rückläufe) ansehen und über ihren Link in SharePoint öffnen.','Vertragskarten bieten einen aufklappbaren eigenen Dokumentbereich.'],['Die SharePoint-Integration muss ausdrücklich freigegeben sein.','Service-Leserecht erlaubt die Liste; In SharePoint öffnen erfordert zusätzlich die dortige Benutzerberechtigung.','Ablage: Objekte/Stadt/Straße_Hausnummer/Gewerk/Einheit/Ablagetyp; Kunden ohne Einheit unter Kunden/Kundenname_Kundennummer; Aufträge bei der Einheit ihres Einsatzes mit der Auftragsnummer am Dateinamen.','Angezeigt werden maximal 100 Dateien der Akte; fremde Ordner werden nicht automatisch zugeordnet.'],['src/platform/sharepoint/document-panel.tsx','src/apps/servicehub/akten/workspace.tsx']),
 feature('service','Dokument manuell nach SharePoint hochladen','/servicehub','write','datei upload hochladen dokument pdf foto sharepoint wiederholen',[ 'In einer Akte den Bereich Dokumente · SharePoint öffnen.','Datei auswählen, unter Ablegen unter den Ablagetyp wählen und Hochladen wählen.','Nach Verbindungsfehler denselben Upload erneut versuchen; die Datei bleibt im geöffneten Fenster ausgewählt.'],['SharePoint-Freigabe und Service-Schreibrecht oder Administrator sind erforderlich. Elli führt selbst keine Dokumentuploads aus.','Unterstützt werden PDF, PNG, JPEG, DOCX, XLSX und UTF-8-Text bis 8 MiB je Datei.','Ein gleicher Upload desselben Benutzers wird anhand von Name und Inhalt wiedererkannt. Bestehende Dateien und neuere Änderungen werden nicht überschrieben.','Vor Neuladen ist eine unbestätigte lokale Datei nicht dauerhaft im Browser gesichert. Danach dieselbe Originaldatei erneut auswählen.'],['src/platform/sharepoint/document-panel.tsx','src/platform/sharepoint/documents.ts']),
 feature('einstellungen','Browser-Schutz und Verletzungsmeldungen prüfen','/einstellungen?bereich=security&seite=security%3Abrowser','admin','browser csp skript blockiert sicherheit verletzung meldungen nonce',[ 'Einstellungen → Sicherheit → Browser-Schutz öffnen.','Unter Browser-Schutz die betroffene Regel, Quellenart, letzte Meldung und Anzahl ansehen.'],['Browsermeldungen angemeldeter Benutzer werden ohne vollständige URLs oder Inhalte zusammengefasst. Sie sind Hinweise und kein Nachweis eines Angriffs.','Skripte benötigen eine Freigabe pro Seitenaufruf. Entwicklungswerkzeuge und Inline-Stile haben dokumentierte Ausnahmen. Es gibt keinen Schalter zum Abschalten des Schutzes.'],['src/platform/http-safety/headers.ts','src/platform/http-safety/reports.ts','src/platform/http-safety/panel.tsx']),
 feature('konto','Eigene Daten exportieren und gezielt bereinigen','/benutzerkonto?bereich=account&seite=account%3Adata','read','datenschutz datenexport auskunft löschen aufbewahrung chat bewertung email sitzungen',[ 'Benutzerkonto → Daten & Export öffnen.','Export herunterladen liefert persönliche Daten als vertrauliche JSONL-Datei.','Für eine Bereinigung Datenarten und Stichtag wählen, Vorschau prüfen und ausdrücklich bestätigen.'],['Es wird nichts automatisch gelöscht. Offene Fragen und Kalenderentwürfe bleiben erhalten.','Gemeinsame Fachakten, Nachweise, Uploads, Wiederholungsschutz und Sicherungen werden nicht gelöscht.','Administratoren können unter Einstellungen → Sicherheit → Daten & Aufbewahrung Prüfhinweise und Sperren festlegen; Entwurfsinhalte exportiert nur der Kontoinhaber.'],['src/platform/data-lifecycle/panel.tsx','src/platform/data-lifecycle/repository.ts','src/platform/data-lifecycle/export.ts']),
 feature('konto','Kalenderentwürfe sicher aufbewahren','/benutzerkonto?bereich=account&seite=account%3Adevice','read','gerät entwürfe verschlüsselt bereinigen abmelden gemeinsamer mac wiederherstellen sicherung',[ 'Benutzerkonto → Gerät & Entwürfe öffnen.','Sichern und entfernen wählen. Erst nach bestätigter Sicherung die lokalen Kalenderkopien entfernen und abmelden.','Nach erneutem Anmelden den PlanBoard öffnen; gesicherte Zweige werden wiederhergestellt.'],['Kalenderentwürfe werden pro Benutzer verschlüsselt aufbewahrt. Noch offene Entwürfe werden nicht automatisch nach Alter gelöscht.','Bei fehlgeschlagener Sicherung wird nichts entfernt. Neuere Eingaben während der Bestätigung bleiben erhalten.','Die Gerätebereinigung betrifft Kalenderkopien. Sie ersetzt keine vollständige Browser- oder Gerätebereinigung. Ohne vorher bestätigte Sicherung gibt es nach Löschen der Browserdaten keine Wiederherstellungsgarantie.'],['src/apps/planboard/entwuerfe/device-panel.tsx','src/apps/planboard/entwuerfe/client.ts','src/apps/planboard/entwuerfe/storage.ts']),
 feature('einstellungen','Geschützte Zugangsdaten aufräumen','/einstellungen?bereich=security&seite=security%3Asecrets','admin','geheimnisdateien zugangsdaten archiv wiederherstellen bereinigung',[ 'Einstellungen → Sicherheit → Geschützte Zugangsdaten öffnen.','Geschützte Zugangsdaten zeigt die Ablagen für BMACloud, Copilot, PDS und Microsoft Graph ohne Geheimnisse. Jetzt prüfen prüft aktive Referenzen und Sicherheitsfristen.','Vorherigen Stand wiederherstellen nur nach bewusster Bestätigung wählen; anschließend erneut prüfen und freigeben.'],['Aktive Zugangsdaten und bis zu zwei vorherige Stände innerhalb von sieben Tagen sind geschützt.','Verwaiste Dateien werden erst nach mindestens 24 Stunden und erneuter Referenzprüfung entfernt. Unklare oder unsichere Dateien bleiben zur Prüfung erhalten.','Eine Wiederherstellung deaktiviert die Integration und entwertet den Verbindungstest. Keine Zugangsdaten in Elli eingeben.'],['src/platform/secret-retention/panel.tsx','src/platform/secret-retention/lifecycle.ts']),
 feature('service','BMACloud-Anlage öffnen','/servicehub?ansicht=files','read','bmacloud bma anlage anlagennummer aid wartungskostenträger vertrag link technische einheit',[ 'Service → Kunden & Objekte öffnen und eine technische Einheit auswählen.','Unter Wartungsverträge den Wartungskostenträger ansehen. Seine Nummer wird exakt mit der BMACloud-Anlagennummer verglichen, einschließlich führender Nullen.','In BMACloud öffnen wählen. Bei mehreren Treffern anhand AID und Anlagenort die passende Anlage auswählen.'],['Die BMACloud-Anbindung muss durch einen Administrator eingerichtet, geprüft und freigegeben sein. Elli kennt die aktuelle Freigabe nicht und aktiviert nichts.','Der Rechnungskostenträger dient nicht der Zuordnung. Ohne passenden Treffer wird kein Anlagenlink erfunden.','Im BMACloud-Portal gelten dessen eigene Anmeldung und Rechte. Ein Link versendet kein API-Token und speichert dort keine Änderung.'],['src/platform/bmacloud/guide.ts','src/platform/bmacloud/mapping.ts','src/apps/servicehub/akten/workspace.tsx']),
 feature('einstellungen','BMACloud einrichten','/einstellungen?bereich=bmacloud&seite=bmacloud:guide','admin','bmacloud anbindung adresse token leserecht anleitung aid freigabe',[ 'Einstellungen → Integrationen → BMACloud → Anleitung öffnen.','Unter Verbindung die HTTPS-Installationsadresse und das API-Token im geschützten Formular eingeben und speichern.','Unter Prüfung & Freigabe die Verbindung testen und anschließend ausdrücklich aktivieren.'],['Die API-Zuordnung liest Anlagen; sie erteilt keine Schreibrechte. Neue Zugangsdaten deaktivieren die Anbindung und erfordern eine erneute Prüfung.','Tokens niemals in Elli eingeben. Elli kann keine Zugangsdaten, aktuellen Einstellungen oder Anlagen abrufen.'],['src/platform/bmacloud/guide.ts','src/platform/bmacloud/repository.ts']),
 feature('service','Aufträge markieren und filtern','/servicehub?ansicht=orders','read','auftrag markieren markiert fahne auftragsfilter filteroptionen pausieren',[ 'Service → Aufträge öffnen, einen Auftrag wählen und die Fahne neben dem Auftragsstatus anklicken. Eine aktive Fahne erneut anklicken, um die Markierung zu entfernen.','Markiert in der Seitenleiste öffnet die persönliche Liste. Unter dem Listenkopf zeigt die aktive Planungskategorie ihr Symbol und ihren Namen. Über … in der Filterkapsel lassen sich Markiert, Planung und Auftragsstatus kombinieren.','Der rechte Auftragsfilter pausiert die ausgewählten Kriterien und stellt sie beim erneuten Einschalten wieder her.'],['Markierungen gelten für das eigene Konto und die aktuelle Datenquelle. Service-Leserecht genügt.'],['src/apps/servicehub/akten/order-filters.tsx','src/apps/servicehub/akten/file-toolbar.tsx','src/apps/servicehub/akten/flag-server.ts']),
 feature('service','Aufträge mit der Tastatur sichten','/servicehub?ansicht=orders','read','auftragsliste tastatur pfeiltasten enter escape akte fokus',[ 'Service → Aufträge öffnen und eine Zeile anklicken oder mit Tab fokussieren. Pfeil nach oben und unten wechseln zwischen sichtbaren Aufträgen, auch von einer direkt geöffneten Aktenüberschrift aus.','Enter öffnet die Akte. Escape führt zur gewählten Zeile zurück. Am Desktop bleibt die Akte beim Sichten sichtbar.'],['Auf schmalen Ansichten ersetzt die Akte nach Enter die Liste. Escape führt zur gewählten Zeile zurück.'],['src/apps/servicehub/akten/workspace.tsx']),
 feature('service','Cockpit und Arbeitslisten','/servicehub','read','kennzahl kachel ungeplant fehlend übersicht wartung fällig überfällig globale suche service durchsuchen auftragsnummer technische einheit',[ 'ServiceHub → Cockpit öffnen. Die Kennzahlen sind nach Aufträgen und Wartungen gruppiert.','Eine Zahl oder Beschriftung wählen, um direkt die passende Arbeitsliste zu öffnen. Ein Klick auf eine Vorschau öffnet die zugehörige Akte.','Fällig bis heute enthält auch überfällige Wartungen. Fälligkeit prüfen öffnet Einträge ohne eindeutige Fälligkeit.','Die Lupe im Cockpit durchsucht Aufträge, Wartungen, Kunden, Objekte und technische Einheiten. Treffer öffnen die Akte direkt. Der Stift links öffnet die Auftragserfassung.'],['Wartungszahlen erscheinen nach vollständiger Abfrage der Datenquelle. Elli kann aktuelle Werte nicht abrufen.'],['src/apps/servicehub/akten/cockpit.tsx','src/apps/servicehub/akten/cockpit-search-model.ts','src/apps/servicehub/akten/workspace.tsx','src/apps/servicehub/akten/server.ts']),
 feature('service','Auftragsakte öffnen','/servicehub?ansicht=orders','read','auftrag akte beschreibung nummer suchen',[ 'In der Service-Seitenleiste Aufträge wählen.','Oben rechts über die Lupe nach Kunde, Objekt, Adresse, Kostenträger oder Auftragsnummer suchen. Vorschläge per Klick oder mit Pfeiltasten und Enter öffnen. Planung im Kopf der Auftragsliste per Kategorie wählen. Status und weitere Kriterien stehen unter … oben rechts im Listenkopf.','Einen Auftrag anklicken; die Akte öffnet sich rechts neben der Liste und zeigt Beschreibung und Einsätze. Fehlen Termin oder Haupttechniker, öffnet das rote Kalendersymbol „Einsatz planen“ den Planungsdialog. Das Stiftsymbol „Neuer Auftrag“ links in der Werkzeugleiste öffnet CaseDesk.'],['Auf kleinen Bildschirmen ersetzt die Akte die Liste. Escape führt zur Liste zurück.','Das Cockpit hebt zuerst Aufträge ohne Termin, danach Aufträge ohne Haupttechniker in einem Hinweisbalken hervor.'],['src/apps/servicehub/akten/workspace.tsx']),
 feature('service','Kunden- und Objektakte','/servicehub?ansicht=files','read','kontakt ansprechpartner adresse technische einheit wartungsvertrag kostenträger kostentraeger nummer wartung rechnung',[ 'Service → Kunden & Objekte öffnen.','Im Listenkopf zwischen Alle, Angeheftet und Mit offenen Aufträgen wählen. Die Lupe oben rechts öffnet die Suche mit Vorschlägen für Kunden, Objekte und technische Einheiten. Ein Klick auf eine Kundenzeile öffnet ihre Akte. Der Pfeil am Zeilenende klappt die Objekthierarchie auf. Pfeil nach oben und unten wechseln die Zeile, Enter öffnet die Akte und Escape führt zur gewählten Zeile zurück. Die Pinnadel neben dem Auge in der Kundenakte heftet den Kunden in der Seitenleiste an. Blaue Markierungen zählen offene Aufträge, orangefarbene Markierungen fällige Wartungen. Aufgeklappte Objekte und Einheiten zeigen ihre eigenen Zähler.','Kundenakte öffnen oder ein Objekt beziehungsweise eine technische Einheit auswählen.','Kundenakten betonen Kundennummer, Anschrift und Ansprechpartner. Objektakten zeigen Kunde, Objektadresse, Objektnummer und Kostenträger; technische Einheiten zusätzlich Standort, TE-Nummer sowie Hersteller und Typ. Weitere Angaben, Verträge, Chronik, Dokumente und zugehörige Aufträge bleiben in klaren Gruppen erreichbar.','Die Service-Suche findet auch Nummer und Bezeichnung des Objekt-/Einheitenkostenträgers sowie Wartungs- und Rechnungskostenträger aus Verträgen. Passende Kostenträger erscheinen direkt am Objekt oder an der technischen Einheit mit Nummer und Bezeichnung, getrennt als eigener Kostenträger, Wartung oder Rechnung. Die zusätzlichen Suchdaten laden im Hintergrund; ein Hinweis zeigt Fortschritt oder unvollständige Ergebnisse.','Das Kundensymbol öffnet die Kundenakte. Die Symbole Objekt und Einheit öffnen Auswahlmenüs. Zum geöffneten Auftrag gehörende Ziele stehen zuerst und sind mit „Passend zum Auftrag“ gekennzeichnet. Das Auftragssymbol führt aus den über die Aktenleiste geöffneten Akten zum Ausgangsauftrag zurück.','Wenn PDS einen gültigen webLink liefert, In PDS öffnen oder PDS-Link kopieren in der jeweiligen Akte wählen.'],['Die Akten sind lesend; Elli erhält keine Akteninhalte.'],['src/apps/servicehub/akten/workspace.tsx','src/apps/servicehub/akten/entity-summary.tsx','src/apps/servicehub/akten/file-toolbar.tsx','src/apps/servicehub/akten/reader.ts','src/apps/servicehub/akten/cost-search-reader.ts','src/apps/servicehub/akten/use-cost-search.ts']),
 feature('stoerung','Terminvergabe ohne neuen Auftrag','/servicehub?ansicht=orders','write','bestehend ungeplant haupttechniker nachplanen terminvergabe',[ 'Service → Aufträge öffnen und einen Einsatz ohne Termin oder Haupttechniker auswählen.','In der Auftragsakte Termin vergeben öffnen.','Haupttechniker, Datum und Uhrzeit, Einsatzdauer und bei Bedarf Begleiter festlegen und speichern.'],['Plant den vorhandenen Einsatz, ohne einen neuen Auftrag anzulegen.','Zwischenzeitliche Änderungen werden geprüft und nicht still überschrieben. Die Terminvergabe wird nur mit Planungsrecht und bei einer Datenanbindung angeboten, die diese Änderung unterstützt.','Die automatische Verfügbarkeitsprüfung bietet freie Haupttechniker und zusammenhängende Zeitfenster für das gewählte Team innerhalb von 14 Tagen. Fehlende Arbeitszeit- oder Urlaubsdaten werden nicht als frei bewertet. Mehrdeutige Startzeiten bei der Zeitumstellung werden übersprungen; die vollständige Dauer muss weiterhin in das freie Zeitfenster passen. Die Prüfung ist eine Momentaufnahme ohne Reservierung.'],['src/apps/servicehub/akten/planning-dialog.tsx','src/apps/servicehub/akten/planning-server.ts','src/apps/casedesk/erfassung/planning-fields.tsx','src/apps/planboard/verfuegbarkeit/model.ts']),
 feature('stoerung','Störung in vier Schritten erfassen','/casedesk','write','störung neu meldung auftragsnummer kontakt objekt',[ 'CaseDesk öffnen.','Schritt 1: Objekt und technische Einheit auswählen. Mit Service-Leserecht zeigt die Anlagenchronik Einsätze, Wartungen und Unterlagen zur gewählten technischen Einheit.','Schritt 2: Meldung und Kontakt erfassen.','Schritt 3: Haupttechniker, Zeitpunkt, Dauer und bei Bedarf Begleiter festlegen oder Schritt überspringen wählen, um später zu planen.','In Schritt 4 (Abschluss) den vollständigen Meldungstext und die Auftragsdaten prüfen, bei Bedarf eine PDS-Bemerkung ergänzen und einen Projektleiter zuweisen. Bei Bedarf Nach dem Anlegen mobil ausgeben einschalten und den angezeigten Haupttechniker prüfen. Anschließend Serviceauftrag speichern wählen. Nach erfolgreicher Anlage führen unter Weiteren Auftrag aufnehmen Direktlinks zur Auftragsakte im Service und bei zugeordnetem Termin zum PlanBoard.'],['Die Erfassung ist nur verfügbar, wenn die angebundene Datenquelle Neuanlagen unterstützt.','Neue Dokumentuploads: maximal 100 MiB pro Datei, 250 MiB pro Konto und 1 GiB gemeinsam mit abgelegten Dokumentkopien. Erkennbare ausführbare Binärdateien werden abgewiesen. Quoten löschen keine vorhandenen Dateien oder Entwürfe.','Bei ausgelastetem System oder langsamer Übertragung bleiben Eingaben erhalten. Kurz warten und denselben Vorgang erneut versuchen; bestätigte Uploads behalten ihre Kennung.','Mobile Ausgabe ist standardmäßig aus und benötigt Haupttechniker und Termin. Eine Wiederholung derselben Speicherung legt keinen neuen Auftrag an. Die Abschlusslinks erscheinen nur mit Leserecht in der Ziel-App; ohne Termin gibt es keinen Kalenderlink.','Datum als TT.MM.JJJJ eingeben oder über die Kalenderauswahl wählen; Uhrzeit separat. Einsatzdauer in Schritt 3: 15 bis 1440 Minuten, in 15-Minuten-Schritten. Zeitangaben gelten für Deutschland. Die Verfügbarkeit wird automatisch geprüft: belegende Termine, genehmigter Urlaub, Arbeitszeiten, Pausen und Feiertage. Freie Haupttechniker oder bis zu drei zusammenhängende Zeitfenster für das gewählte Team innerhalb von 14 Tagen lassen sich übernehmen. Ohne ausreichende Daten bleibt die Verfügbarkeit unbekannt. Keine Reservierung; Eignung und Anfahrt selbst prüfen.'],['src/apps/casedesk/erfassung/incident-form.tsx','src/apps/casedesk/erfassung/planning-fields.tsx','src/apps/planboard/verfuegbarkeit/model.ts','src/app/(protected)/casedesk/page.tsx']),
 feature('ressourcen','Kalenderwoche und Datum auswählen','/planboard','read','kw kalenderwoche heute datum anzeigen tag woche monat',[ 'PlanBoard öffnen.','Tag, Woche oder Monat wählen.','Über die KW-/Datumsauswahl den Zeitraum auswählen; die Pfeile wechseln den Zeitraum, Heute springt zum aktuellen Datum.'],['Kalenderwochen können über Jahresgrenzen reichen.'],['src/apps/planboard/kalender/calendar.tsx']),
 feature('ressourcen','Wochenende ein- und ausblenden','/planboard','read','wochenende samstag sonntag sa so ausblenden',[ 'Im PlanBoard Darstellung (Reglersymbol) öffnen und den Wochenendschalter ändern.','Samstag und Sonntag werden gemeinsam ein- oder ausgeblendet.'],['Das Ausblenden ist eine Anzeigeänderung, es verschiebt keine gespeicherten Termine.'],['src/apps/planboard/kalender/calendar.tsx']),
 feature('ressourcen','Ressourcen und Mitarbeiter auswählen','/planboard','read','ressourcenauswahl techniker fachgruppe gruppe suchen',[ 'In der Werkzeugleiste Mehr (⋯) → Ressourcenauswahl öffnen.','Mitarbeiter oder Ressourcengruppen auswählen und übernehmen.','Die Mitarbeitersuche grenzt die angezeigten Ressourcen ein.'],['Die Ressourcenauswahl wird benutzerbezogen gespeichert.'],['src/apps/planboard/kalender/resource-selection-dialog.tsx','src/apps/planboard/kalender/postgres-settings.ts']),
 feature('ressourcen','Termin-Kontextmenü und Doppelklick','/planboard','read','einfachklick doppelklick rechtsklick kontextmenü öffnen vollständig',[ 'Einfach auf einen Termin klicken, um sein seitliches Kontextmenü zu öffnen.','Direkt auf einen Termin doppelklicken, um die vollständige Bearbeitung zu öffnen.','Bei einem Termin mit Serviceauftrag öffnet Im Service öffnen die zugehörige Auftragsakte. Dafür ist zusätzlich Lesezugriff auf Service erforderlich.'],['Änderungen benötigen Schreibrecht in der jeweiligen App oder Administrator. Ein geöffneter Termin erteilt keine Schreibrechte.'],['src/apps/planboard/kalender/calendar.tsx','src/apps/planboard/kalender/quick-menu.tsx','src/apps/planboard/kalender/calendar-http.ts']),
 feature('ressourcen','Termin verschieben und verlängern','/planboard','write','ziehen drag drop verschieben verlängern kürzen dauer resize',[ 'Im PlanBoard den Termin auf die gewünschte Position ziehen oder seine zeitliche Ausdehnung anpassen.','Alternativ den Termin doppelklicken und Beginn, Ende oder Dauer ändern und speichern.'],['Fixierte oder gerade speichernde Termine lassen sich nicht verschieben.','Die angebundene Datenquelle muss Terminänderungen unterstützen; bei einer ausschließlich lesenden Anbindung ist die Bearbeitung gesperrt.'],['src/apps/planboard/kalender/calendar.tsx','src/apps/planboard/kalender/option-fields.tsx']),
 feature('ressourcen','Fixierung ändern','/planboard','write','fixierung fixiert entsperren sperre aufheben',[ 'Termin doppelklicken.','Unter Zeit & Status den Schalter Fixiert ändern.','Weitere Änderungen vornehmen und speichern.'],['Das Abwählen erlaubt die Bearbeitung der Felder; erst Speichern übernimmt die Änderung.'],['src/apps/planboard/kalender/calendar.tsx','src/apps/planboard/kalender/option-fields.tsx']),
 feature('ressourcen','Zeit, Dauer und ganztägige Termine','/planboard','write','beginn ende dauer minuten ganztags ganzer tag',[ 'Termin vollständig öffnen.','Unter Zeit & Status Beginn, Ende und Dauer in Minuten bearbeiten oder Ganzer Tag umschalten.','Änderungen speichern.'],['Ein ganztägiger Termin endet um 00:00 Uhr am ausschließlichen Enddatum.','Dauer im PlanBoard: mindestens 15 Minuten, maximal 62 Tage.'],['src/apps/planboard/kalender/option-fields.tsx']),
 feature('ressourcen','Kategorien, Status und PIM','/planboard','write','kategorie anzeigen als frei geplant pim synchronisation',[ 'Termin doppelklicken.','Anzeigen als und PIM-Synchronisation unter Zeit & Status bearbeiten.','Kategorien über die farbigen Kategorieschalter auswählen und speichern.'],['Bereitschaft erzwingt den Status Frei.','PIM-Synchronisation benötigt eine eingerichtete PDS-Synchronisation; ein Schalter bestätigt deren Verfügbarkeit nicht.'],['src/apps/planboard/kalender/option-fields.tsx']),
 feature('ressourcen','Terminhistorie ansehen','/planboard','read','historie änderung benutzer zeitpunkt vorher nachher',[ 'Termin vollständig öffnen.','Die Historie im Terminfenster ausklappen.'],['HeyElli protokolliert eigene Änderungen mit Benutzer, Zeitpunkt sowie alten und neuen Werten.','Das ist keine aus PDS importierte vollständige Vergangenheit.'],['src/apps/planboard/kalender/calendar.tsx','src/apps/planboard/kalender/change-audit.ts']),
 feature('ressourcen','Einzelnen Serviceauftrag mobil ausgeben','/planboard','write','mobil ausgabe haupttechniker pds mobilität',[ 'Serviceauftrag im Terminfenster oder über sein Kontextmenü öffnen.','Mobil ausgeben wählen und den Haupttechniker vor der Ausgabe prüfen.','Ausgabe bestätigen.'],['Die Ausgabe wird mit Benutzer und Zeitpunkt in der Terminhistorie protokolliert.','Mobil ausgeben setzt einen Serviceauftrag mit Haupttechniker und eine Datenanbindung voraus, die diese Aktion unterstützt.'],['src/apps/planboard/kalender/calendar.tsx','src/apps/planboard/kalender/mobile-issue.tsx']),
 feature('ressourcen','Mehrere Serviceaufträge mobil ausgeben','/planboard','write','alle heute sammel ausgabe aktuell anzeige',[ 'In der Werkzeugleiste Mobil ausgeben öffnen.','Alle Serviceaufträge heute ausgeben oder Alle Serviceaufträge ausgeben wählen.','Die Auswahl und den Ausgabevorgang prüfen und bestätigen.'],['Alle bezieht sich auf die aktuelle Anzeige einschließlich Filter und sichtbarer Ressourcen. Nur ausgabefähige Serviceaufträge mit Haupttechniker werden berücksichtigt; jeder Auftrag wird einmal ausgegeben.'],['src/apps/planboard/kalender/bulk-mobile.tsx']),
 feature('ressourcen','Serviceauftrag stornieren','/planboard','write','storniert manuell storniert abgeholt stornieren',[ 'Termin-Kontextmenü öffnen und Auftrag stornieren aufklappen.','Statuswahl und Bestätigung im Untermenü prüfen.'],['Mobil abgeholte Aufträge verwenden Manuell storniert; andere Aufträge Storniert.','Stornieren und Termin löschen sind unterschiedliche Vorgänge.'],['src/apps/planboard/kalender/calendar.tsx']),
 feature('ressourcen','Termin umbenennen oder löschen','/planboard','write','umbenennen titel löschen entfernen sicherheitsabfrage',[ 'Einfachklick auf den Termin öffnet das Kontextmenü.','Umbenennen oder Löschen seitlich aufklappen.','Neuen Namen übernehmen oder die Sicherheitsabfrage im Lösch-Untermenü bestätigen.'],['Löschen nicht mit Stornieren eines Serviceauftrags verwechseln.'],['src/apps/planboard/kalender/calendar.tsx']),
 feature('ressourcen','Teamübersicht öffnen','/planboard','read','teamübersicht team zusammen kunde objektadresse uhrzeit',[ 'In der PlanBoard-Werkzeugleiste Mehr (⋯) und dann Teamübersicht wählen.','Die Woche wählen und pro Techniker Uhrzeiten, Kunden, Objektadressen sowie Haupt- und Begleittechniker ansehen.'],['Die vollständige Einsatzbesetzung bleibt auch bei eingeschränkter Ressourcenauswahl erkennbar.'],['src/apps/planboard/kalender/team-overview.tsx']),
 feature('ressourcen','Speicherung, Verbindungsabbruch und Konflikte','/planboard','write','offline netzwerk kringel ladekringel entwurf wiederholen konflikt',[ 'Während eine Speicherung läuft, kann der übrige Kalender weiter bedient werden.','Ein Termin mit Ladekringel lässt sich öffnen; seine Felder sind bis zum Abschluss deaktiviert.','Bei Verbindungsrückkehr werden vorgemerkte Änderungen erneut versucht.'],['Unabhängige Änderungen werden automatisch zusammengeführt. Nur widersprüchliche Änderungen am selben Feld benötigen eine Entscheidung; Benutzer und Zeitpunkt werden angezeigt.','Sicherungen liegen im Hintergrund; bei deaktiviertem oder gelöschtem Browser-Speicher gelten Grenzen der lokalen Wiederherstellung.'],['src/apps/planboard/kalender/calendar.tsx']),
 feature('ressourcen','Planungshinweise und Überbuchung','/planboard','write','warnung arbeitszeit pause feiertag überschneidung kapazität überbuchung trotzdem',[ 'Bei Planungshinweisen die Warnungen pro Mitarbeiter prüfen.','Weiter bearbeiten wählen, um Zeit oder Besetzung anzupassen, oder Trotzdem speichern ausdrücklich bestätigen.'],['Warnungen betreffen unter anderem Arbeitszeit, Pausen, Feiertage, Überschneidungen, Überbuchung oder nicht vollständig prüfbare Kapazität.','Im CaseDesk und bei Termin vergeben im Service gibt es zusätzlich eine automatische Verfügbarkeitsprüfung mit freien Technikern und zusammenhängenden Zeitfenstern.'],['src/apps/planboard/kalender/planning-warnings.ts','src/apps/planboard/kalender/planning-warning-dialog.tsx']),
 feature('ressourcen','Suche und Kapazitätszahlen','/planboard','read','soll abwesend belegt rest restkapazität ressourcen termine suche',[ 'Im Suchfeld der Werkzeugleiste einen Begriff eingeben und wählen, ob er Ressourcen eingrenzt oder Termine hervorhebt. Beide Filter können gleichzeitig mit unterschiedlichen Begriffen aktiv sein und erscheinen als Kapseln.','Nicht passende Termine werden abgeblendet statt ausgeblendet; die Belegung bleibt sichtbar.','Die Leiste am unteren Rand zeigt Ressourcen sowie Soll, Abwesend, Belegt und Rest, soweit berechenbar; Neu laden fordert eine Aktualisierung an.'],['Fehlende Restkapazität bedeutet keine bestätigte Verfügbarkeit.','Terminfilter verändern die Einzelkapazität nicht.','Die Teamübersicht übernimmt Ressourcenauswahl, Terminfilter und Wochenendanzeige.'],['src/apps/planboard/kalender/calendar.tsx','src/apps/planboard/kalender/team-overview.tsx']),
 feature('maildesk','MailDesk-Postfach einrichten','/einstellungen?bereich=graph&seite=graph:maildesk','admin','maildesk postfach einrichten geteiltes postfach microsoft 365 graph mail.read verbindung prüfen beispielpostfach quelle',[ 'Einstellungen → Integrationen → Microsoft Graph → MailDesk-Postfach öffnen.','Quelle Microsoft 365 wählen und die Adresse des geteilten Postfachs eintragen.','Verbindung prüfen: prüft Anmeldung und Lesezugriff auf den Posteingang, ohne Inhalte zu lesen. Danach speichern.'],['Speichern mit Microsoft 365 ist erst nach einer erfolgreichen Prüfung dieses Postfachs in den letzten 24 Stunden möglich.','Voraussetzung ist die zentrale Microsoft-365-App unter Microsoft Graph mit der Anwendungsberechtigung Mail.Read, per Zugriffsrichtlinie auf das Postfach begrenzt.'],['src/apps/maildesk/settings-panel.tsx','src/apps/maildesk/settings.ts']),
 feature('maildesk','Mails automatisch Kunden zuordnen','/maildesk','read','maildesk mail email postfach geteilt zuordnen kostenträger ktr auftragsnummer kundennummer absender vorschlag',[ 'MailDesk öffnen. Jede Mail zeigt ein Kennzeichen: grün zugeordnet, orange Vorschlag, grau nicht zugeordnet.','Automatisch zugeordnet wird über Kostenträger im Betreff, Auftragsnummer, Kundennummer, Kostenträger im Text oder einen bekannten Absender. Gehört ein Kostenträger mehreren Kunden, entscheidet ein zweiter Hinweis wie die Adresse.','Adresse oder Kundenname allein ergeben nur einen Vorschlag: unter Vorschlag prüfen mit Übernehmen bestätigen oder Anderer Kunde wählen.','Nach Bestätigen oder manuellem Zuordnen wird der Absender gelernt und künftig automatisch erkannt.'],['Zuordnungen gelten für das Postfach und die aktive PDS-Quelle.','Mailinhalte werden nicht in HeyElli gespeichert.'],['src/apps/maildesk/matching.ts','src/apps/maildesk/server.ts','src/apps/maildesk/workspace.tsx']),
 feature('maildesk','Serviceauftrag aus einer Mail anlegen','/maildesk','write','serviceauftrag anlegen aus mail störungsmeister vorausgefüllt mail anhängen auftrag verknüpfen',[ 'Eine zugeordnete Mail öffnen und Serviceauftrag anlegen wählen.','Der CaseDesk öffnet sich mit Objekt, Beschreibung, Meldeweg Per E-Mail und der Mail als Dokument. Fehlende Angaben ergänzen und speichern.','Nach dem Speichern wird der Auftrag mit der Mail verknüpft; die Mail steht unter Auftrag angelegt.','Für einen bestehenden Auftrag unter Beim Kunden Mail anhängen wählen.'],['Nur verfügbar, solange der CaseDesk neue Aufträge anlegen darf.','Benötigt Schreibrecht im CaseDesk.'],['src/apps/casedesk/erfassung/mail-prefill.ts','src/apps/maildesk/server.ts']),
 feature('service','Kunde 360: alles zu einem Kunden','/servicehub?ansicht=files','read','kunde 360 kundenübersicht zeitleiste nächster termin vor ort kennzahlen offene aufgaben mails notizen kundenakte',[ 'ServiceHub → Alle Kunden öffnen und einen Kunden wählen (Kundenakte).','Oben steht der nächste Termin vor Ort mit Datum, Anlage und Zuständigen, darunter Kennzahlen zu Vorgängen, Aufgaben, Mails der letzten sieben Tage und Objekten.','Termine vor Ort und offene PDS-Aufgaben stehen in eigenen Karten; die Zeitleiste zeigt Mails, Aufgaben, Vorgänge und Notizen, filterbar nach Art.','Notiz wählen, um einen Vermerk am Kunden zu speichern (höchstens 2000 Zeichen); eigene Notizen lassen sich in der Zeitleiste löschen.'],['Termine vor Ort umfassen feste und vorgemerkte Besuche der nächsten acht Wochen an den Objekten und Einheiten des Kunden.','Aufgaben und Mails erscheinen nur mit Lesezugriff auf Aufgaben bzw. MailDesk.','Notizen speichert HeyElli, da PDS Gesprächsnotizen nicht über die Schnittstelle anbietet; Notizen anlegen benötigt Schreibrecht im Service.'],['src/apps/servicehub/kunde360/server.ts','src/apps/servicehub/kunde360/customer-overview.tsx','src/apps/servicehub/kunde360/notes-store.ts','src/platform/pds/api/visits.ts']),
 feature('missioncontrol','Tag planen und im Fokus arbeiten','/missioncontrol','read','missioncontrol tag planen woche wichtig heute fokus timer pomodoro notizen schritte konzentriert arbeiten innendienst',[ 'MissionControl öffnen. Unter Heute bis zu drei Aufgaben mit dem Stern als wichtig markieren oder in die freien Felder ziehen.','Weitere Aufgaben über Planen einem Tag zuordnen oder in der Wochenübersicht auf einen Tag ziehen.','Mit ▶ den Fokus starten: Timer, Pause, +5 Minuten und Erledigt. Schritte (S) und Notizen (M) einzeln einblenden; Notizen auf Wunsch beim Erledigen an die PDS-Beschreibung anhängen.','Unter Ziele Teamziele mit Zielwert und Zeitraum anlegen; der Wert kommt automatisch aus PDS und Service oder wird gepflegt. Aufgaben lassen sich einem Ziel zuordnen; der Rückblick zeigt die Woche im Vergleich zur Vorwoche.'],['Planung, Fokuszeiten und Notizen speichert HeyElli; die Aufgaben stammen aus der App Aufgaben.','Erledigen ist nur für PDS-Aufgaben möglich, solange die PDS-Anbindung Schreibzugriffe erlaubt; Mails und Aufträge werden in MailDesk bzw. im Service bearbeitet.','Planen benötigt Schreibrecht in MissionControl und Lesezugriff auf Aufgaben.','Mit dem Schalter Fokusblöcke in Outlook eintragen erscheinen eingeplante Aufgaben als Termin im eigenen Outlook-Kalender; Verschieben dort wird übernommen. Voraussetzung ist ein zugeordnetes Microsoft-Konto und die Kalenderberechtigung der Microsoft-365-App.'],['src/apps/missioncontrol/server.ts','src/apps/missioncontrol/calendar.ts','src/apps/missioncontrol/store.ts','src/apps/missioncontrol/workspace.tsx']),
 feature('aufgaben','Meine Aufgaben ansehen','/taskhub','read','aufgaben meine aufgaben to-do wiedervorlage rückruf überfällig heute diese woche warten team pds aufgabe crm',[ 'TaskHub öffnen. Standard sind die eigenen offenen Aufgaben, gruppiert nach Überfällig, Heute, Diese Woche, Später und Ohne Datum.','Links nach Ansicht, Quelle (PDS-Aufgaben, zugewiesene Mails, noch nicht terminierte Serviceaufträge) oder Person im Team filtern; über alle die Aufgaben des ganzen Teams zeigen.','Eine Aufgabe öffnen: Kunde, Objekt, Zuständige, Fälligkeit, Beschreibung, Checkliste und die nächsten Termine vor Ort am Objekt.'],['PDS-Aufgaben stammen aus dem CRM von PDS; berücksichtigt werden die ersten 300 offenen Aufgaben.','Mails und Aufträge werden in MailDesk bzw. im Service bearbeitet.'],['src/apps/taskhub/server.ts','src/apps/taskhub/workspace.tsx','src/platform/pds/api/crm.ts']),
 feature('aufgaben','Aufgabe anlegen und bearbeiten','/taskhub','write','aufgabe anlegen neue aufgabe zuweisen status erledigt warten checkliste fällig pds crm rückruf',[ 'In TaskHub auf Neue Aufgabe (Stift) klicken.','Betreff, Typ aus PDS, Fälligkeit, Zuständige (PDS-Benutzer), Kunde und Objekt sowie Beschreibung angeben; optional eine Checkliste mit einem Schritt je Zeile.','Anlegen speichert die Aufgabe in PDS. Status, Zuweisung und Erledigt lassen sich im Detail ändern; Checkliste und Verknüpfungen bleiben in HeyElli.','Aus einer Mail in MailDesk: Aufgabe wählen. Betreff, Mailtext sowie Kunde und Objekt aus der Zuordnung sind vorbelegt, die Mail wird mit der Aufgabe verknüpft.'],['PDS erlaubt je Aufgabe entweder ein Objekt oder eine Projektakte.','Anlegen und Ändern in PDS ist nur möglich, solange die PDS-Anbindung Schreibzugriffe erlaubt; bei rein lesender Anbindung Status und Zuweisung in PDS ändern.','Benötigt Schreibrecht in Aufgaben und einen zugeordneten PDS-Benutzer.'],['src/apps/taskhub/create-dialog.tsx','src/apps/taskhub/server.ts','src/platform/pds/api/crm.ts']),
 feature('maildesk','Antworten, zuweisen, markieren und archivieren','/maildesk','write','antworten zuständig zuweisen mir zugewiesen markieren archivieren team rücklauf termin angebot rechnung',[ 'Mit Antworten eine Antwort an den Absender schreiben; sie läuft über den zentralen Mailversand.','Unter Zuständig eine Person wählen; eigene Mails stehen unter Mir zugewiesen.','Markieren und Archivieren gelten für alle im Postfach.','Kennzeichen helfen beim Sortieren: Rücklauf, Termin, Angebot, Lieferant und Störung.'],['Ist der zentrale Mailversand gesperrt, wird die Antwort nicht zugestellt; In Outlook antworten bleibt möglich.','Archiv und Markierung ändern nichts im Microsoft-365-Postfach.'],['src/apps/maildesk/store.ts','src/apps/maildesk/workspace.tsx']),
 feature('bereitschaft','Bereitschaft direkt zuweisen','/dutyboard','write','zuweisen kw jahresübersicht mitarbeiter dialog folgewochen hintereinander',[ 'DutyBoard → Jahresübersicht öffnen.','Eine freie Mitarbeiter-/KW-Zelle anklicken.','Mitarbeiter, KW und Zeitraum im Vordergrunddialog prüfen und Zuordnung speichern wählen.'],['Nur noch nicht begonnene Wochen können zugewiesen werden. Der Mitarbeiter muss für die gesamte Woche planbar sein; Abwesenheiten und persönliche Sperrwochen werden berücksichtigt.','Fixierte oder abweichende Bereitschaften werden hier nicht ersetzt. Reguläre Bereitschaft: Montag 07:00 bis zum folgenden Montag 07:00, Status Frei.','Zwei aufeinanderfolgende Wochen warnen; eine manuelle Zuweisung ist nach ausdrücklicher Bestätigung möglich.'],['src/apps/dutyboard/overview.tsx','src/apps/dutyboard/assignment-dialog.tsx']),
 feature('bereitschaft','Bereitschaft aufteilen oder löschen','/dutyboard','write','splitten teilen zweiter teil zeitpunkt kontextmenü löschen',[ 'Eine bestehende Bereitschaft in der Jahresübersicht anklicken.','Im Kontextmenü Splitten, Zum PlanBoard oder Löschen wählen.','Zum Splitten einen Teilungszeitpunkt und den Mitarbeiter für den zweiten Teil wählen.'],['Nur nicht fixierte freie Bereitschaftstermine mit genau einem Mitarbeiter lassen sich teilen. Der Teilungszeitpunkt muss innerhalb des Termins und in der Zukunft liegen; der zweite Mitarbeiter muss für den zweiten Teil verfügbar sein.','Splitten arbeitet mit mehreren Schreibschritten. Nach Teilfehlern denselben Vorgang fortsetzen; neuere Änderungen werden nicht still überschrieben. Fixierte Bereitschaften können auch nicht über dieses Menü gelöscht werden.'],['src/apps/dutyboard/event-menu.tsx','src/apps/dutyboard/split.ts']),
 feature('bereitschaft','Ressourcen übernehmen und speichern','/dutyboard','read','ressourcenplan übernehmen mitarbeiterauswahl dauerhaft',[ 'Neben der Jahresauswahl Ressourcen auswählen öffnen oder Aus Ressourcenplan übernehmen wählen.','Die Mitarbeitersuche unter den Reitern zum Eingrenzen nutzen.'],['Auswahl und Feiertagseinstellungen werden dauerhaft pro Benutzer gespeichert. Die Übernahme ist eine ausdrücklich ausgelöste Übernahme, kein behaupteter ständiger Gleichlauf.'],['src/apps/dutyboard/overview.tsx']),
 feature('bereitschaft','Automatische Neuverteilung','/dutyboard','write','automatisch verteilen gerecht neuplanen vorschau fortsetzen',[ 'Jahr und teilnehmende Ressourcen auswählen.','Den Reiter Automatisch verteilen öffnen und die Feiertagseinstellungen prüfen.','Automatisch verteilen wählen.','Vorschau mit Mitarbeiterbegründungen und ersetzten Terminen prüfen.','Neuplanung verbindlich übernehmen oder Verwerfen wählen.'],['Bestehende geschützte oder bereits geleistete Bereitschaften werden berücksichtigt. Nicht besetzbare Wochen werden ausgewiesen.','Eine unterbrochene Übernahme lässt sich fortsetzen; Restliche Planung beenden erhält bereits übernommene Wochen.','Automatische Verteilung vermeidet aufeinanderfolgende Wochen; eine Warnbestätigung bei manueller Zuweisung ist kein allgemeiner Automatismus.'],['src/apps/dutyboard/overview.tsx','src/apps/planboard/kalender/duty.ts']),
 feature('bereitschaft','Urlaub und Sperrwochen','/dutyboard','linked','urlaub abwesenheit sperrzeit ausschließen nicht verfügbar',[ 'DutyBoard → Sperrzeiten & Tausch öffnen.','Unter Meine Sperrwochen eine noch nicht begonnene KW auswählen und ausschließen.'],['Für eigene Sperrwochen ist eine Mitarbeiterzuordnung erforderlich. Schreibrecht in der jeweiligen App oder Administrator können auch fremde Sperrwochen wieder freigeben.','Urlaub und Abwesenheiten mit anderem Status als Frei sperren die Verteilung bereits; persönliche Sperrwochen kommen zusätzlich hinzu.','Besteht schon eine Bereitschaft, einen Tausch vorschlagen statt diese Woche auszuschließen.'],['src/apps/dutyboard/wishes.tsx','src/apps/dutyboard/wishes-server.ts']),
 feature('bereitschaft','Tauschwunsch vorschlagen und freigeben','/dutyboard','linked','tausch tauschen zustimmen partner freigeben zurückziehen',[ 'DutyBoard → Sperrzeiten & Tausch öffnen.','Eigene Bereitschaft und die Bereitschaft des Tauschpartners auswählen und einen Tausch vorschlagen.','Der Tauschpartner stimmt zu.','Anschließend gibt die Planung den Tausch ausdrücklich frei.'],['Zum Vorschlagen brauchen beide Mitarbeiter eindeutige aktive Benutzerzuordnungen. Für die anschließende Freigabe genügt Schreibrecht in der jeweiligen App oder Administrator; die freigebende Person benötigt keine eigene Mitarbeiterzuordnung.','Nur vollständige zukünftige, nicht fixierte freie Bereitschaftswochen mit jeweils einer Ressource sind tauschbar. Verfügbarkeit und Folgewochen werden erneut geprüft.','Antragsteller können zurückziehen; Partner oder Planung können ablehnen. Freigabe benötigt Planungsrecht.'],['src/apps/dutyboard/wishes.tsx','src/apps/dutyboard/wishes-server.ts']),
 feature('bereitschaft','Feiertage und mehrjähriger Rückblick','/dutyboard','read','feiertag neujahr weihnachten ostern pfingsten bundesland rückblick gewichtung',[ 'Automatisch verteilen → Feiertage berücksichtigen einschalten.','Bundesland und Rückblick auswählen.','Gewichtung & Ortsregeln für Neujahr, Weihnachten, Ostern, Pfingsten und sonstige Feiertage festlegen.'],['Geleistete und geschützte Bereitschaften sowie ausgewählte Vorjahre gehen in die Bewertung ein.','Ortsregeln für Bayern, Sachsen und Thüringen passend zum Einsatzort wählen. Heiligabend und Silvester sind nicht in der Feiertagswertung enthalten.','Feiertagswochen sind auch bei ausgeschalteter Gewichtung dezent markiert.'],['src/apps/dutyboard/holiday-options.tsx','src/apps/planboard/kalender/duty-fairness.ts']),
 feature('bereitschaft','Fairnesskonto und Tageszählung','/dutyboard','read','fairnesskonto punkte geleistet tage runden letzte übernahme',[ 'Den Reiter Fairnesskonten öffnen.','Bereitschaftstage, noch geplante Tage, Feiertagspunkte und letzte Übernahmen von Neujahr, Weihnachten, Ostern und Pfingsten vergleichen.'],['Tagesanzeigen werden ab 0,5 aufgerundet, darunter abgerundet. Verteilung und Punkte rechnen mit genauen Zeiten.','Geleistet bedeutet vergangene Zeit geplanter Termine, kein tatsächlicher Arbeitszeitnachweis.','Ein Strich bei letzter Übernahme bedeutet keinen gefundenen vergangenen Eintrag im Bewertungszeitraum.'],['src/apps/dutyboard/fairness-accounts.tsx','src/apps/dutyboard/overview.tsx']),
 feature('konto','Apps finden und Navigation','/','read','logo spotlight suche app raster liste tastatur navigation',[ 'Auf das HeyElli-Logo klicken oder Strg/⌘ K drücken.','App oder Bereich suchen; Kategorien unter dem Suchfeld filtern.','Mit Pfeiltasten wählen, Enter öffnen und Escape schließen.','Raster- oder Listenansicht oben im Menü wählen.'],['Die Menüansicht wird pro Benutzer gespeichert.','Im App-Menü neben den Navigationspfeilen stehen Über, Hilfe und gegebenenfalls Einstellungen. Auf dem Smartphone zeigt es das App-Symbol mit Abwärtspfeil.'],['src/platform/shell/app-launcher.tsx','src/platform/shell/current-app-menu.tsx']),
 feature('konto','Werkzeuge in der Menüleiste','/benutzerkonto?bereich=tools','read','tools werkzeug menüleiste kompakt störungsmeister einblenden ausblenden',[ 'Das Symbol des CaseDesks links neben dem Benutzermenü öffnet seine mobile Ansicht.','Mit dem X oder einem Klick außerhalb zuklappen; beim erneuten Öffnen im selben geöffneten HeyElli-Fenster bleiben Eingaben erhalten.','Benutzerkonto → Werkzeuge öffnen und freigegebene Werkzeuge persönlich ein- oder ausblenden.'],['Administratoren geben Werkzeuge unter Einstellungen → Benutzer & Zugriff → Rollen & App-Zugriffe → gewünschte Rolle frei. App-Werkzeuge wie CaseDesk benötigen zusätzlich Zugriff auf ihre App und verwenden deren Schreibrechte. Das persönliche Notizen-Werkzeug hat eine eigene Rollenfreigabe ohne Fach-App-Schreibrecht.','Administratoren haben alle Werkzeuge. Persönliches Einblenden erteilt keine Rollenrechte.','Bei Smartphone-Breite bis einschließlich 650 Pixel sind Menüleisten-Werkzeuge ausgeblendet. Die vollständige App bleibt über das HeyElli-Menü erreichbar.','Die Sichtbarkeit wird pro Benutzer automatisch gespeichert. Ein roter Punkt am Werkzeugsymbol kennzeichnet einen noch nicht angelegten Auftrag. Im Werkzeug werden angefangene Erfassungen pro Benutzer verschlüsselt gesichert und nach Neuladen oder Schließen beim erneuten Öffnen fortgesetzt. Mehrere Tabs erhalten getrennte Erfassungen; weitere gesicherte Erfassungen lassen sich im Werkzeug auswählen. Nach einer unklaren Speicherantwort nur Speicherergebnis prüfen wählen: derselbe Vorgang wird ohne doppelte Anlage wiederholt. Bei fehlgeschlagener lokaler Sicherung schützt der Neuladehinweis die noch offenen Eingaben. Dateien sind nach bestätigter geschützter Ablage auf diesem Browsergerät wiederherstellbar; noch nicht fertig gesicherte Dateien erfordern das geöffnete Fenster.'],['src/platform/app-access/tools.ts','src/platform/app-access/repository.ts','src/platform/shell/menu-tools.tsx','src/platform/shell/navigation-guard.tsx','src/system/benutzerkonto/tools-preferences.tsx','src/apps/casedesk/erfassung/incident-form.tsx','src/apps/casedesk/erfassung/tool-draft-client.ts','src/apps/casedesk/erfassung/tool-draft-files.ts']),
 feature('konto','Funktionen im Benutzerkonto suchen','/benutzerkonto','read','einstellungen suche unterseiten funktion tastatur profil anzeige werkzeuge',[ 'Links in Einstellungen suchen einen Funktionsnamen eingeben.','Treffer links mit ihrem Einstellungsweg prüfen, per Klick öffnen oder mit Pfeiltasten und Enter auswählen.','Escape oder Suche löschen leert das Feld. Der Suchtext bleibt beim Öffnen eines Treffers erhalten.'],['Die Suche im Benutzerkonto enthält ausschließlich die eigenen Kontofunktionen. Keine Benutzerwerte oder Zugangsdaten werden indexiert.'],['src/platform/shell/settings-search.ts','src/platform/shell/settings-search-navigation.tsx']),
 feature('einstellungen','Einstellungsfunktionen suchen','/einstellungen','admin','suche suchfeld funktionen index unterseiten einstellungen',[ 'In Einstellungen suchen den Namen einer Funktion eingeben, zum Beispiel Sitzungsdauer oder Mitarbeiterzuordnung.','Die Treffer erscheinen links mit dem Einstellungsweg. Klick oder Pfeiltasten und Enter öffnen die Zielseite.','Escape oder Suche löschen leert das Feld. Nicht gespeicherte Änderungen bleiben durch den Navigationsschutz geschützt.'],['Ein Treffer aktiviert keine Integration und ändert keine Einstellung. Bedingte Funktionen benötigen weiterhin ihre Freigabe. Es werden nur statische Funktionsnamen und Suchbegriffe indexiert.'],['src/platform/shell/settings-search.ts','src/platform/shell/settings-search-navigation.tsx']),
 feature('konto','Persönliche Darstellung ändern','/benutzerkonto?bereich=display','read','hell dunkel theme darstellung system gerät anzeigen',[ 'Benutzermenü → Benutzerkonto → Anzeige öffnen.','Hell, Dunkel oder Wie Gerät wählen.'],['Die persönliche Darstellung wird automatisch gespeichert. Zentrale Standarddarstellung ist eine getrennte Administratorvorgabe.'],['src/system/benutzerkonto/personal-settings-workspace.tsx','src/system/benutzerkonto/appearance-choice.tsx']),
 feature('konto','Profil und Mitarbeiterzuordnung','/benutzerkonto','read','profil rolle angemeldet mitarbeiter benutzerkonto',[ 'Benutzerkonto → Profil öffnen.','Angemeldeten Benutzer, Rolle und zugeordneten Mitarbeiter ansehen.'],['Die Mitarbeiterzuordnung wird durch einen Administrator unter Einstellungen → Benutzer & Zugriff → Benutzerkonten geändert, nicht im eigenen Profil.'],['src/system/benutzerkonto/account-profile-card.tsx','src/system/benutzerkonto/account-profile.ts']),
 feature('einstellungen','Benutzerrollen und Freischaltung','/einstellungen?bereich=users','admin','benutzer aktivierung aktivieren deaktivieren freischalten rollen automatisch',[ 'Einstellungen → Benutzer & Zugriff öffnen.','Benutzerkonten zum Bearbeiten oder Benutzer freischalten zum Hinzufügen öffnen.','Rolle, Aktivierung und Mitarbeiterzuordnung beim gewünschten Benutzer ändern.'],['Rollen, Aktivierung und Mitarbeiterzuordnung speichern automatisch. Neue Benutzer werden ausdrücklich über Benutzer freischalten angelegt.','Rollenänderungen oder Sperrungen widerrufen bestehende Sitzungen. Der letzte aktive Administrator muss erhalten bleiben.'],['src/system/einstellungen/admin-panel.tsx','src/system/einstellungen/server.ts']),
 feature('einstellungen','Eigene Rollen und App-Zugriffe','/einstellungen?bereich=users&seite=users:roles','admin','rollen rolleneditor app freigeben sperren zugriff eigene berechtigung',[ 'Einstellungen → Benutzer & Zugriff → Rollen & App-Zugriffe öffnen.','In der Rollenliste eine bestehende Rolle zur Bearbeitung öffnen oder Neue Rolle anlegen wählen.','Bestehende Rollen speichern Änderungen automatisch. Bei einer neuen Rolle Namen und je App Kein Zugriff, Lesen oder Lesen & Schreiben festlegen und Rolle speichern wählen; erst dann wird sie angelegt.','Benutzer & Zugriff → Benutzerkonten öffnen, einen Benutzer auswählen und unter Rolle die Standardrolle oder eigene Rolle auswählen; die Zuordnung speichert unmittelbar.'],['Administratoren haben immer vollständigen Zugriff. Eigene Rollen gelten für Nicht-Administratoren.','Lese- und Schreibrechte gelten pro App; Hilfe hat nur Zugriff. Eigene Einstellungen bleiben mit App-Zugriff bearbeitbar. App-Rechte trennen keine einzelnen Datensätze.','Änderungen widerrufen betroffene Sitzungen. Nur unzugeordnete eigene Rollen lassen sich löschen.'],['src/platform/app-access/editor.tsx','src/platform/app-access/repository.ts','src/proxy.ts']),
 feature('einstellungen','heyelli-Konto anlegen und PDS-Benutzer zuordnen','/einstellungen?bereich=users','admin','konto benutzer anlegen benutzername startpasswort passwort zurücksetzen pds benutzer mitarbeiter bearbeiter zuordnung microsoft verknüpfen upn',[ 'Benutzer & Zugriff → Konto anlegen: Anzeigename, Benutzername, Rolle, PDS-Benutzer und optional Microsoft-Anmeldeadresse eintragen. Startpasswort erzeugen ist vorausgewählt.','Konto anlegen speichert alles in einem Schritt. Das Startpasswort erscheint danach einmalig mit Kopieren-Knopf; sicher übergeben, bei der ersten Anmeldung muss es geändert werden.','Im geöffneten Konto alle Felder ändern und gemeinsam mit Änderungen speichern sichern; beim Verlassen mit ungespeicherten Eingaben fragt HeyElli nach. Ein neues Startpasswort ist ebenfalls nur einmal sichtbar.'],['Ohne PDS-Benutzer kann sich ein Konto nicht anmelden (Administratoren ausgenommen). Die Zuordnung gilt je PDS-Quelle.','Ein PDS-Benutzer kann nur einem Konto zugeordnet sein; offene Tauschwünsche blockieren einen Wechsel.','Nach Aktivierung der Microsoft-Anmeldung meldet sich ein Konto nur noch mit dem verknüpften Microsoft-Konto an.'],['src/system/einstellungen/account-panel.tsx','src/platform/store/repository.ts']),
 feature('konto','Eigenes Passwort ändern oder Microsoft-Konto verknüpfen','/benutzerkonto?bereich=account&seite=account%3Alogin','read','passwort ändern kennwort neues passwort microsoft verknüpfen entra anmeldung',[ 'Benutzermenü → Benutzerkonto → Anmeldung öffnen.','Unter heyelli-Passwort das bisherige und zweimal das neue Passwort eingeben.','Mit Microsoft verknüpfen wählen, sobald die Administration die Microsoft-Anmeldung eingerichtet hat.'],['Das Passwort braucht mindestens 12 Zeichen; andere angemeldete Geräte werden abgemeldet.','Elli sieht weder Passwörter noch den Verknüpfungsstatus.'],['src/system/benutzerkonto/account-profile-card.tsx','src/system/anmeldung/anmeldung/password-form.tsx']),
 feature('einstellungen','Sitzungsdauer und Sitzungen','/einstellungen?bereich=security&seite=security%3Asessions','admin','sitzungsdauer sitzungszeitraum ablaufen widerrufen anmelden',[ 'Einstellungen → Sicherheit → Sitzungsdauer öffnen und den Sitzungszeitraum ändern.','Aktive Sitzungen unter Benutzer & Zugriff → Sitzungen ansehen und bei Bedarf widerrufen.'],['Systemeinstellungen speichern automatisch. Die Sitzungsdauer gilt ab der nächsten Anmeldung; bestehende Sitzungen behalten ihren Ablaufzeitpunkt. Abgelaufene oder widerrufene Sitzungen führen zum Anmeldebildschirm.','Elli kann keine Sitzung verlängern, widerrufen oder Sitzungswerte offenlegen.'],['src/system/einstellungen/settings-panel.tsx','src/system/einstellungen/admin-panel.tsx']),
 feature('einstellungen','Kalenderfarben und Reihenfolge','/einstellungen?bereich=colors','admin','farben farbreihenfolge priorität hauptfarbe nebenfarbe kategorie status',[ 'Einstellungen → PlanBoard → Kalenderfarben öffnen.','Termin-Konfiguration, Termin-Kategorien oder Statusfarbe auswählen.','Farbe oder Farbreihenfolge ändern und die automatische Speicherbestätigung abwarten.'],['Die Legende im Kalender erklärt Farben, sie bearbeitet keine zentralen Farben.','Haupt- und Nebenfarbe folgen den zentralen Regeln; vorhandene PDS-Farben können Vorrang haben.'],['src/apps/planboard/kalender/color-dialog.tsx','src/platform/shell/settings-page-model.ts']),
 feature('einstellungen','Zentrale Kalender-Anzeigevorgaben','/einstellungen?bereich=colors','admin','anzeigevorgaben ressourcenmeister zentral standard',[ 'Einstellungen → PlanBoard → Anzeigevorgaben öffnen.','Zentrale Vorgaben bearbeiten.'],['Persönliche Darstellung bleibt separat im Benutzerkonto.'],['src/system/einstellungen/admin-workspace.tsx','src/platform/shell/settings-page-model.ts']),
 feature('einstellungen','Änderungsprotokoll filtern und exportieren','/einstellungen?bereich=users','admin','audit markdown download kopieren filter zeitraum änderungsart',[ 'Benutzer & Zugriff → Änderungsprotokoll öffnen.','Suche, Benutzer, Zeitraum und Änderungsart einstellen.','Zum Kopieren über eine Zeile fahren und das dezente Kopiersymbol wählen.','Beim Markdown-Download alle oder nur gefilterte Einträge wählen.'],['Alte und neue Werte, Benutzer und Zeitpunkt sind auch in Kopie und Download enthalten.','Nicht mit der einzelnen Terminhistorie verwechseln.'],['src/system/einstellungen/audit-panel.tsx']),
 feature('mail','Outlook öffnen statt Graph versenden','/einstellungen?bereich=email','admin','outlook new online mailto empfänger betreff nachricht',[ 'Einstellungen → Organisation → E-Mail öffnen.','Empfänger, Betreff und Nachricht erfassen.','In Outlook öffnen wählen und die Nachricht im Mailprogramm selbst prüfen und versenden.'],['Die Übergabe versendet nicht selbst. Sie nutzt das Standard-Mailprogramm und garantiert nicht die Auswahl einer bestimmten Outlook-Variante.','Ohne aktive Graph-Integration erscheinen keine Graph-Versandoptionen.'],['src/system/einstellungen/mail-panel.tsx']),
 feature('mail','Microsoft Graph einrichten und prüfen','/einstellungen?bereich=graph','admin','graph ms365 tenant client secret absender postfach verbindung',[ 'Einstellungen → Integrationen → Microsoft Graph → Verbindung öffnen.','Zentrales Absenderpostfach festlegen; die automatische Speicherung abwarten.','Die Microsoft-365-Daten im geschützten Formular hinterlegen.','Gespeichertes Postfach prüfen und Anleitung für die Microsoft-365-Administration öffnen.'],['Die Einrichtung benötigt Daten und Berechtigungen des Microsoft-365-Administrators. Secret nur im geschützten Formular eingeben, niemals in Elli.','Die Postfachprüfung bestätigt noch keine Versandberechtigung. Die Versandberechtigung muss für das zentrale Postfach eingerichtet sein.'],['src/system/einstellungen/mail-guide-content.ts','src/system/einstellungen/mail-panel.tsx']),
 feature('mail','Graph-Versand, Freigabe und Warteschlange','/einstellungen?bereich=graph','admin','versand freigeben warteschlange fehler nachricht erneut senden',[ 'Microsoft Graph → Prüfung & Freigabe öffnen.','Für den Versand eine erfolgreiche Prüfung des aktuellen Postfachs innerhalb der letzten 24 Stunden und einen bereiten Dienst sicherstellen und ausdrücklich freigeben.','In E-Mail → Warteschlange und Versandprotokoll die Verarbeitung verfolgen.'],['Eine Annahme durch Microsoft ist keine Zustellbestätigung.','Unklare Versandergebnisse nicht blind erneut versenden; zuerst in Exchange prüfen.','Nach Absender- oder Zugangsdatenwechsel sind Prüfung und Versandfreigabe erneut erforderlich.'],['src/system/einstellungen/mail-guide-content.ts','src/platform/mail/repository.ts','src/platform/mail/worker.ts']),
 feature('einstellungen','Betriebsstatus und Alarme','/einstellungen?bereich=security&seite=security%3Aoperations','admin','überwachung alarm betriebsstatus datenbank warteschlange unklar versand störung',[ 'Einstellungen → Sicherheit → Betriebsstatus öffnen.','Die lokale Entwicklungsumgebung startet ihren Überwachungsdienst mit passender IPv4-/IPv6-Loopback-Adresse automatisch und beendet ihn beim Stoppen sauber. Lebenszeichen, Warteschlange und aktive Alarme prüfen. Ein Alarm lässt sich als gelesen bestätigen.','Bei unklarem Versand zuerst Exchange prüfen; bei unklarer Elli-Aktion Termin oder Auftrag und Historie abgleichen.'],['Nur Administratoren können Betriebsstatus lesen und Alarme bestätigen.','Bestätigen behebt keine Störung. Keine automatische Wiederholung unklarer Fachaktionen.','Der lokale Überwachungsdienst muss laufen; ohne aktuelles Lebenszeichen ist der Status nicht bestätigt.'],['src/platform/operations/panel.tsx','src/platform/operations/probe.ts','scripts/dev.mjs','scripts/monitor.mjs','scripts/monitor-lease.mjs']),
 feature('einstellungen','PDS-Anbindung sicher vorbereiten','/einstellungen?bereich=pds','admin','pds api datenansichten views bearbeiter anbindung',[ 'Einstellungen → Integrationen → PDS-Anbindung öffnen.','Verbindung, API-Prüfung, Datenansichten, Bearbeiter und Quelle & Freigabe durchgehen.','Die Anleitung mit den offenen Fragen für den PDS-Administrator lesen und als Markdown herunterladen.'],['Die PDS-Anbindung unterstützt derzeit ausschließlich Lesezugriffe. Die Quellenfreigabe aktiviert keine Schreibfunktionen.','Dokumentierte API hat Vorrang. Datenansichten schließen nur nachgewiesene Feldlücken und bleiben lesend. Kein stiller Fallback bei API-Fehlern.','Elli liest weder Verbindungsdaten noch aktuelle Freigabezustände.'],['src/system/einstellungen/pds-guide.ts','src/system/einstellungen/pds-panel.tsx','src/platform/pds/connection/source.ts']),
 feature('einstellungen','Microsoft-Anmeldung vorbereiten','/einstellungen?bereich=microsoft-auth','admin','microsoft anmeldung oauth entra tenant freigabe anmelden',[ 'Einstellungen → Integrationen → Microsoft-Anmeldung öffnen.','Verbindung einrichten, Prüfung & Freigabe durchführen und die Anleitung für die Microsoft-365-Administration verwenden.'],['Die Anmeldung wird erst durch ausdrückliche Freigabe eines Administrators aktiviert. Elli kennt den aktuellen Aktivierungsstatus nicht.','Nach der Aktivierung ersetzt sie die eigene Anmeldung: Das Passwortfeld entfällt und bestehende lokale Sitzungen sind gesperrt. Deaktivieren stellt die eigene Anmeldung wieder her.','Sie ist eine eigene Integration und nicht identisch mit Microsoft Graph für den Mailversand.','Zugangsdaten nur im geschützten Formular eingeben. Elli prüft keine Verbindung.'],['src/system/anmeldung/microsoft/guide.ts','src/system/anmeldung/microsoft/panel.tsx']),
 feature('einstellungen','Copilot einrichten und freigeben','/einstellungen?bereich=copilot','admin','copilot studio elli externe ki bot direct line secret verbindung freigabe',[ 'Einstellungen → Integrationen → Copilot öffnen.','Verbindung: Bot-ID und Direct-Line-Secret geschützt speichern. Ein leeres Secret-Feld erhält das vorhandene Secret.','Prüfung & Freigabe: Verbindung testen. Erst anschließend Copilot aktivieren bestätigen und Copilot freigeben wählen.','Anleitung enthält die Einrichtung für die Microsoft-Administration und ist als Markdown herunterladbar.'],['Ein veröffentlichter eigener Copilot-Studio-Agent mit dokumentiertem Antwort-Topic und passender Lizenz ist erforderlich.','Der Verbindungstest aktiviert nichts. Jede Konfigurationsänderung deaktiviert Copilot und entwertet den bisherigen Test.','Copilot ersetzt die lokale KI nur im aktiven Status. Bei inaktivem Copilot nutzt Elli Ollama. Aktionen benötigen weiterhin Schreibberechtigung und eine separate Bestätigung.'],['src/apps/askelli/copilot/panel.tsx','src/apps/askelli/copilot/repository.ts','src/apps/askelli/copilot/guide.ts']),
 feature('hilfe','Elli, Gespräch und Neuer Chat','/','read','elli chat kontext neuer chat verlauf frage eingabe enter',[ 'Eine Bedienungsfrage eingeben oder einen der Fragevorschläge anklicken.','Enter sendet, Umschalt+Enter erzeugt eine neue Zeile.','Mit Rückfragen an das bisherige Gespräch anknüpfen.','Neuer Chat setzt Fragen, Antworten, vorgemerkte Anfragen und gesicherte Eingaben zurück und lässt eine frische Begrüßung erzeugen.'],['Ohne aktiven Copilot steht Elli als lokale Bedienungshilfe mit Ollama zur Verfügung. Für Fachaktionen muss Copilot eingerichtet und freigegeben sein.','Schreibaktionen benötigen Schreibrecht in der jeweiligen App oder Administrator und eine separate Bestätigung in HeyElli.','Keine Geheimnisse eingeben.'],['src/apps/askelli/elli/chat.tsx','src/apps/askelli/elli/server.ts']),
 feature('hilfe','Ellis Antworten bewerten','/einstellungen?bereich=elli','admin','bewertung feedback daumen hilfreich rückmeldung grund',[ 'Unter einer gespeicherten eigenen Antwort Daumen hoch oder Daumen runter wählen.','Bei Daumen runter optional einen Grund auswählen und einen Hinweis ergänzen; Grund speichern übernimmt diese Ergänzung.','Eine ausgewählte Bewertung erneut anklicken, um sie zu entfernen.','Unter Einstellungen → Apps → AskElli eingereichte Bewertungen mit Frage, Antwort, Quellen und Wissensstand prüfen.'],['Nur Administratoren dürfen Bewertungen abgeben oder lesen; auch direkte API-Aufrufe prüfen diese Berechtigung.','Nur ausdrücklich bewertete eigene Antworten werden mit Frage und Antwort zur Wissenspflege gespeichert. Sie bleiben nach Neuer Chat erhalten. Eigene Bewertungen lassen sich dort auch später entfernen.','Keine automatische Übernahme ins Wissen oder Modelltraining. Keine vertraulichen Angaben in den Hinweis eingeben.'],['src/apps/askelli/elli/answer-feedback.tsx','src/apps/askelli/elli/feedback-review.tsx','src/platform/store/assistant-feedback.ts','src/app/api/assistent/bewertungen/route.ts']),
 feature('hilfe','Gesicherte Fragen wiederherstellen','/','read','entwurf nicht abgesendet tab schließen verbindung abbruch offline',[ 'AskElli nach erneutem Öffnen laden lassen.','Gesicherte nicht abgesendete Fragen stehen wieder im Fragefeld; weitere Eingabestände unter Weitere gesicherte Fragen.','Offene gesendete Fragen werden mit gleicher Kennung fortgesetzt.'],['Verfügbarer Browser-Speicher ist für sofortige lokale Sicherung erforderlich. Keine Garantie nach Löschen von Browserdaten.','Ohne laufende Umgebung und geöffnetes Elli gibt es keinen eigenständigen Wiederanlaufdienst.'],['src/apps/askelli/elli/chat.tsx','src/platform/store/assistant-chats.ts']),
 feature('einstellungen','Standardpositionen für Störungsaufträge','/einstellungen?bereich=incident&seite=incident:positions','admin','störungsmeister standardposition standardpositionen artikel katalog positionsnummer menge vorlage',[ 'Einstellungen → Apps → CaseDesk → Standardpositionen öffnen.','Position hinzufügen wählen, einen PDS-Katalogartikel suchen und auswählen sowie Positionsnummer und Menge eintragen. Vollständige Angaben werden automatisch gespeichert.','Die Vorgaben werden neuen Störungsaufträgen vor einer optionalen mobilen Ausgabe hinzugefügt.'],['Nur Administratoren dürfen die Vorgaben ändern. Name und Artikeltyp stammen aus dem gewählten Katalogartikel.','Bis zu 20 Positionen mit eindeutigen Positionsnummern und Mengen größer null. Die Vorgaben gelten getrennt je Datenquelle.','Bestehende Aufträge bleiben unverändert. Wiederholungen derselben Auftragsanlage verwenden denselben Vorgabenstand und erzeugen keine doppelten Positionen.','Offene Eingaben im Einstellungsbereich bleiben erhalten; bei Speicherfehlern erneut versuchen.'],['src/apps/casedesk/standardpositionen/panel.tsx','src/apps/casedesk/standardpositionen/catalog.ts','src/apps/casedesk/standardpositionen/repository.ts','src/platform/pds/simulator/write-gateway.ts','src/platform/pds/api/execute.ts']),
];
